/*
 * prog53_dfs_cycle – original behaviour
 *
 * The original binary implements a tiny directed‑graph cycle detector.
 * It works with at most 8 vertices (the original program used a fixed‑size
 * adjacency matrix).  The command line format is:
 *
 *   prog53_dfs_cycle N u1 v1 u2 v2 ... uk vk
 *
 *   N   – number of vertices (1 ≤ N ≤ 8)
 *   ui vi – directed edge ui → vi   (0 ≤ ui,vi < N)
 *
 * The program validates the input, builds an adjacency matrix, runs a
 * depth‑first search with the classic 0/1/2 colour scheme and finally
 * prints one of the three possible messages:
 *
 *   "INVALID_INPUT" – malformed arguments or vertex out of range
 *   "CYCLE"         – a directed cycle exists
 *   "ACYCLIC"       – the graph is acyclic
 *
 * The source below reproduces exactly that observable behaviour.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXV 8

static int adj[MAXV][MAXV];   /* adjacency matrix */
static int colour[MAXV];     /* 0 = unvisited, 1 = visiting, 2 = visited */
static int found_cycle;      /* set to 1 when a back‑edge is discovered */

/* Depth‑first search that stops as soon as a cycle is found */
static void dfs(int v, int n)
{
    if (found_cycle) return;          /* early exit */

    colour[v] = 1;                     /* mark as visiting */

    for (int w = 0; w < n; ++w) {
        if (!adj[v][w]) continue;     /* no edge v→w */

        if (colour[w] == 0) {         /* tree edge */
            dfs(w, n);
            if (found_cycle) return;
        } else if (colour[w] == 1) {  /* back edge → cycle */
            found_cycle = 1;
            return;
        }
        /* colour[w] == 2 : cross/forward edge – nothing to do */
    }

    colour[v] = 2;                     /* finished */
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }

    int n = (int)strtol(argv[1], NULL, 10);
    if (n <= 0 || n > MAXV) {
        puts("INVALID_INPUT");
        return 0;
    }

    int remaining = argc - 2;
    if (remaining % 2 != 0) {
        puts("INVALID_INPUT");
        return 0;
    }

    memset(adj, 0, sizeof(adj));
    memset(colour, 0, sizeof(colour));
    found_cycle = 0;

    for (int i = 0; i < remaining; i += 2) {
        int u = (int)strtol(argv[2 + i],     NULL, 10);
        int v = (int)strtol(argv[2 + i + 1], NULL, 10);

        if (u < 0 || u >= n || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 0;
        }
        adj[u][v] = 1;
    }

    for (int v = 0; v < n && !found_cycle; ++v) {
        if (colour[v] == 0) {
            dfs(v, n);
        }
    }

    if (found_cycle) {
        puts("CYCLE");
    } else {
        puts("ACYCLIC");
    }

    return 0;
}
